{
    return pol[i];
}

CG3_INLINE const Point2d&Polygon2::operator [](unsigned int i) const
{
    return pol[i];
}

CG3_INLINE void Polygon2::updateBoundingBox()
{
    bb = BoundingBox2();
    if (size() > 0){
        bb.min() = pol[0];
        bb.max() = pol[0];
        for (cg3::Point2d& p : pol){
            bb.min() = bb.min().min(p);
            bb.max() = bb.max().max(p);
        }
    }
}

